/**
 * Gallery data for the marketing pages: the build's catalog (sources-derived
 * detail) joined with public/gallery/index.json (file names, sizes, hashes,
 * signatures). Both are generated by `npm run gallery:build` and imported as
 * static JSON, so the pages need no file-system access at request time.
 */

import catalogJson from './catalog.json'
import indexJson from '@/public/gallery/index.json'
import type { CatalogEntry, GalleryCatalog } from './catalog'
import { GALLERY_CATEGORIES, GALLERY_NEEDS, GALLERY_TRIGGERS, type GalleryCategoryId, type GalleryIndex, type GalleryIndexEntry, type GalleryNeed, type GalleryOrigin, type GalleryTrigger } from './types'

const catalog = catalogJson as unknown as GalleryCatalog
const index = indexJson as unknown as GalleryIndex

export type GalleryPackage = CatalogEntry & { file: GalleryIndexEntry }

const files = new Map(index.packages.map((entry) => [entry.slug, entry]))

/** Every package with its file entry, in category then title order. */
export const GALLERY_PACKAGES: GalleryPackage[] = catalog.packages
  .filter((entry) => files.has(entry.slug))
  .map((entry) => ({ ...entry, file: files.get(entry.slug)! }))

export const GALLERY_SIGNING = index.signing

export const GALLERY_UPDATED = index.updated

export function getGalleryPackage(slug: string): GalleryPackage | undefined {
  return GALLERY_PACKAGES.find((entry) => entry.slug === slug)
}

export function galleryCategory(id: GalleryCategoryId) {
  return GALLERY_CATEGORIES.find((category) => category.id === id)!
}

export function triggerLabel(trigger: GalleryTrigger): string {
  return GALLERY_TRIGGERS[trigger].badge
}

export function needLabel(need: GalleryNeed): string {
  return GALLERY_NEEDS[need]?.label ?? need
}

export function formatBytes(bytes: number): string {
  return bytes < 1024 ? `${bytes} B` : `${(bytes / 1024).toFixed(bytes < 10 * 1024 ? 1 : 0)} KB`
}

/** Packages that share the category (then the trigger), for "related" links. */
export function relatedPackages(pkg: GalleryPackage, limit = 3): GalleryPackage[] {
  return GALLERY_PACKAGES
    .filter((other) => other.slug !== pkg.slug)
    .sort((a, b) => Number(b.category === pkg.category) - Number(a.category === pkg.category) || Number(b.trigger === pkg.trigger) - Number(a.trigger === pkg.trigger))
    .slice(0, limit)
}

/** The card data the client-side browser needs (no workflow graphs). */
export interface GalleryCard {
  /** Detail page (official: /gallery/<slug>, community: /gallery/community/<slug>). */
  href?: string
  source?: GalleryOrigin
  native?: boolean
  systems?: string[]
  author?: string | null
  downloads?: number
  slug: string
  title: string
  summary: string
  category: GalleryCategoryId
  trigger: GalleryTrigger
  needs: GalleryNeed[]
  tags: string[]
  difficulty: string
  setup_minutes: number
  icon: string | null
  steps: number
  version: string
}

export function galleryCards(): GalleryCard[] {
  return GALLERY_PACKAGES.map((pkg) => ({
    href: `/gallery/${pkg.slug}`,
    source: 'official' as const,
    native: pkg.native,
    systems: pkg.systems,
    slug: pkg.slug,
    title: pkg.title,
    summary: pkg.summary,
    category: pkg.category,
    trigger: pkg.trigger,
    needs: pkg.needs,
    tags: pkg.tags,
    difficulty: pkg.difficulty,
    setup_minutes: pkg.setup_minutes,
    icon: pkg.icon ?? null,
    steps: pkg.workflows.reduce((sum, wf) => sum + wf.nodes.length, 0),
    version: pkg.version,
  }))
}

/** A listed community package as a gallery card (lib/services/gallery-community CommunityPackageView). */
export function communityCard(pkg: { slug: string; title: string; summary: string; category: string; trigger: GalleryTrigger; tags: string[]; native: boolean; author_name: string; downloads: number; current_version: string }): GalleryCard {
  return {
    href: `/gallery/community/${pkg.slug}`,
    source: 'community',
    native: pkg.native,
    systems: [],
    author: pkg.author_name,
    downloads: pkg.downloads,
    slug: pkg.slug,
    title: pkg.title,
    summary: pkg.summary,
    category: (GALLERY_CATEGORIES.some((c) => c.id === pkg.category) ? pkg.category : 'operations-compliance') as GalleryCategoryId,
    trigger: pkg.trigger,
    needs: [],
    tags: pkg.tags,
    difficulty: 'intermediate',
    setup_minutes: pkg.native ? 5 : 20,
    icon: null,
    steps: 0,
    version: pkg.current_version,
  }
}
